<?php declare(strict_types=1); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Local Accounts · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'local-accounts',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">ACCESS MANAGEMENT</p><h1>Local accounts</h1><p>Create users who sign in with a username and do not need an email address.</p></div></header><?php if($notice):?><div class="page-flash <?=$notice['type']?>"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><?php if($error):?><div class="form-alert error"><?=esc($error)?></div><?php endif;?><?php if($localCredentials):?><section class="panel"><h2>Copy these credentials now</h2><p>Passwords are shown once. Manually created users must change theirs at first sign-in; full-demo accounts keep the displayed password for repeated testing.</p><?php foreach($localCredentials as $credential):?><div class="planning-row"><span><strong><?=esc($credential['name'])?> · <?=esc(ucfirst($credential['role']))?></strong><small>Username: <?=esc($credential['username'])?></small></span><code><?=esc($credential['password'])?></code></div><?php endforeach;?></section><?php endif;?><section class="planning-grid"><article class="panel"><h2>Organization setting</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_local_account_settings"><label class="check-label"><input type="checkbox" name="allow_local_accounts" value="1" <?=!empty($localAccountSettings['allow_local_accounts'])?'checked':''?>><span>Allow username-only accounts</span></label><button class="button primary">Save setting</button></form><hr><h2>Full demo organization</h2><p>Creates a separate, fully populated sandbox with staff, schedules, requests, coverage, credentials, payroll, master schedules, messages, and every access level.</p><form method="post" onsubmit="return confirm('Create and switch to a new full demo organization?')"><?=Csrf::field()?><input type="hidden" name="action" value="create_full_demo_organization"><button class="button primary">Create full demo organization</button></form><hr><h3>Quick accounts in this organization</h3><p>Creates administrator, scheduler, supervisor, and member accounts without adding the full dataset.</p><form method="post" onsubmit="return confirm('Create four demo accounts in this organization?')"><?=Csrf::field()?><input type="hidden" name="action" value="seed_smoke_accounts"><button class="button secondary">Create quick test accounts</button></form></article><article class="panel"><h2>Add a local user</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="create_local_account"><label>Name<input name="name" required></label><label>Username<input name="username" required pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,39}" autocomplete="off"></label><label>Temporary password<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><label>Role<select name="role"><option value="member">Team member</option><option value="supervisor">Supervisor</option><option value="scheduler">Scheduler</option><option value="admin">Administrator</option></select></label><label>Location<select name="location_id"><option value="">Not assigned</option><?php foreach($data['locations'] as $x):?><option value="<?=$x['id']?>"><?=esc($x['name'])?></option><?php endforeach;?></select></label><label>Department<select name="department_id"><option value="">Not assigned</option><?php foreach($data['departments'] as $x):?><option value="<?=$x['id']?>"><?=esc($x['name'])?></option><?php endforeach;?></select></label><label>Position<select name="position_id"><option value="">Not assigned</option><?php foreach($data['positions'] as $x):?><option value="<?=$x['id']?>"><?=esc($x['name'])?></option><?php endforeach;?></select></label><button class="button primary" <?=empty($localAccountSettings['allow_local_accounts'])?'disabled':''?>>Create local user</button></form></article><article class="panel span-2"><h2>Existing local accounts</h2><?php foreach($localAccountSettings['accounts'] as $account):?><div class="planning-row"><span><strong><?=esc($account['name'])?></strong><small>@<?=esc($account['username'])?> · <?=esc(ucfirst($account['role']))?></small></span><b class="state-pill <?=$account['status']==='active'?'covered':'gap'?>"><?=esc($account['must_change_password']?'Password change required':ucfirst($account['status']))?></b></div><?php endforeach;?><?php if(!$localAccountSettings['accounts']):?><p>No local accounts yet.</p><?php endif;?></article></section></main></body></html>
